const int switch1Pin = 11; // 限位开关1 接 D11
const int switch2Pin = 12; // 限位开关2 接 D12

void setup() {
  // 初始化串口通信，波特率9600
  Serial.begin(9600);

  // 设置引脚为输入模式，并启用内部上拉电阻
  // 这样平时是高电平(HIGH)，按下开关接地后变低电平(LOW)
  pinMode(switch1Pin, INPUT_PULLUP);
  pinMode(switch2Pin, INPUT_PULLUP);

  Serial.println("System Ready. Monitoring switches...");
}

